CREATE TABLE IF NOT EXISTS "settings" (
  "key" text,
  "value" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE IF NOT EXISTS "web_users" (
  "name" text,
  "password_hash" text NOT NULL,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("name")
);

CREATE TABLE IF NOT EXISTS "web_push_devices" (
  "endpoint" text,
  "user_name" text NOT NULL,
  "p256dh" text NOT NULL,
  "auth" text NOT NULL,
  "kinds" text NOT NULL,
  "refused" text NOT NULL DEFAULT '',
  "created_at" bigint NOT NULL,
  "last_sent_at" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("endpoint")
);
CREATE INDEX IF NOT EXISTS "web_push_devices_user" ON "web_push_devices" (user_name);

CREATE TABLE IF NOT EXISTS "web_tab_states" (
  "user_name" text NOT NULL,
  "screen" text NOT NULL,
  "state" text NOT NULL,
  "updated_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("user_name", "screen")
);

CREATE TABLE IF NOT EXISTS "web_room_reads" (
  "user_name" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "message_id" bigint,
  "sent_at" bigint NOT NULL,
  "row_order" bigint NOT NULL,
  "created_at" bigint NOT NULL,
  "read_at" bigint NOT NULL,
  "user_id" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("user_name", "chat_id")
);

CREATE TABLE IF NOT EXISTS "web_palettes" (
  "user_name" text NOT NULL,
  "palette" text NOT NULL,
  "updated_at" bigint NOT NULL,
  "user_id" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("user_name")
);

CREATE TABLE IF NOT EXISTS "web_themes" (
  "user_name" text NOT NULL,
  "theme" text NOT NULL,
  "updated_at" bigint NOT NULL,
  "user_id" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("user_name")
);

CREATE TABLE IF NOT EXISTS "web_presence_hidden" (
  "user_id" bigint,
  "hidden_at" bigint NOT NULL,
  PRIMARY KEY ("user_id")
);

CREATE TABLE IF NOT EXISTS "web_guides" (
  "user_id" bigint,
  "flow" text NOT NULL,
  "step" text NOT NULL,
  "need" text,
  "supply_later" boolean NOT NULL DEFAULT false,
  "road" text,
  "finished_at" bigint,
  "left_at" bigint,
  "updated_at" bigint NOT NULL,
  PRIMARY KEY ("user_id")
);

CREATE TABLE IF NOT EXISTS "document_talk" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "document" text NOT NULL,
  "speaker" text NOT NULL,
  "text" text NOT NULL,
  "said_at" bigint NOT NULL,
  "passage" text,
  "heading" text,
  "version" text,
  "translated" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "document_talk_document" ON "document_talk" (document, id);

ALTER TABLE "web_push_devices" ADD COLUMN IF NOT EXISTS "user_id" bigint;

ALTER TABLE "web_tab_states" ADD COLUMN IF NOT EXISTS "user_id" bigint;

CREATE TABLE IF NOT EXISTS "web_languages" (
  "user_name" text NOT NULL,
  "language" text NOT NULL,
  "updated_at" bigint NOT NULL,
  "user_id" bigint,
  PRIMARY KEY ("user_name")
);
